SCHEMA_SQL = (
    "CREATE OR REPLACE FUNCTION public.protect_fixed_definition()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\n BEGIN\n IF TG_OP='UPDATE' THEN\n IF TG_TABLE_NAME='definition_specs' THEN\n IF OLD.receipt_id IS NULL AND NEW.receipt_id IS NOT NULL\n  AND (to_jsonb(NEW)-'receipt_id') IS NOT DISTINCT FROM (to_jsonb(OLD)-'receipt_id')\n  AND EXISTS(SELECT 1 FROM action_receipts receipt JOIN definition_specs spec\n   ON spec.tenant_id=receipt.tenant_id AND spec.id=NEW.id AND spec.xmin=receipt.xmin\n   WHERE receipt.tenant_id=NEW.tenant_id AND receipt.id=NEW.receipt_id\n    AND receipt.operation IN ('product.definition.item.patch','product.definition.draft','product.definition.update')\n    AND receipt.subject_id=NEW.definition_id AND receipt.subject_type='definition_revision'\n    AND receipt.category_id=NEW.category_id AND receipt.product_id=NEW.product_id\n    AND receipt.actor_id=scope_actor() AND receipt.requester_id=scope_requester()) THEN RETURN NEW; END IF;\n ELSIF TG_TABLE_NAME='definition_revisions' THEN\n IF current_user='pdos_next_owner'\n  AND OLD.status='draft' AND NOT OLD.sealed AND NEW.status='published' AND NEW.sealed\n  AND (to_jsonb(NEW)-ARRAY['status','sealed','publication_receipt_id']) IS NOT DISTINCT FROM\n      (to_jsonb(OLD)-ARRAY['status','sealed','publication_receipt_id']) THEN RETURN NEW; END IF;\n IF (to_jsonb(OLD)->>'sealed')='false' AND (to_jsonb(NEW)->>'sealed')='true'\n AND (to_jsonb(NEW)-ARRAY['sealed','source_proposal_id','source_submission_id','source_proposal_revision','g0_decision_id'])\n   =(to_jsonb(OLD)-ARRAY['sealed','source_proposal_id','source_submission_id','source_proposal_revision','g0_decision_id'])\n AND m3_result_access(NEW.tenant_id,NEW.category_id,'definition_revisions',NEW.id)\n THEN RETURN NEW; END IF;\n END IF;\n END IF;\n RAISE EXCEPTION 'definition snapshots are immutable'; END $function$\n",
    "CREATE OR REPLACE FUNCTION public.m3_definition_item_atom()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE item definition_specs; prior definition_specs; baseline definition_specs; parent definition_revisions;\n receipt action_receipts; actual_run agent_runs; candidate proposal_prepared_candidates; confirmation confirmations;\n call agent_tool_calls; model agent_tool_calls; rx xid; ix xid; payload jsonb; operation jsonb; manifest jsonb;\n business jsonb; expected jsonb; first_version integer; last_version integer; actual_count integer;\n excluded text[]=ARRAY['id','tenant_id','category_id','product_id','definition_id','created_at',\n  'item_id','item_version','removed','prepared_candidate_id','origin','writer_id','run_id','confirmed_by','receipt_id'];\nBEGIN\n SELECT * INTO STRICT item FROM definition_specs WHERE tenant_id=NEW.tenant_id AND id=NEW.id;\n SELECT * INTO STRICT parent FROM definition_revisions WHERE tenant_id=item.tenant_id AND category_id=item.category_id\n  AND product_id=item.product_id AND id=item.definition_id FOR UPDATE;\n SELECT xmin INTO ix FROM definition_specs WHERE tenant_id=item.tenant_id AND id=item.id;\n IF NOT EXISTS(SELECT 1 FROM definition_spec_current current WHERE current.tenant_id=item.tenant_id\n  AND current.category_id=item.category_id AND current.product_id=item.product_id AND current.definition_id=item.definition_id\n  AND current.item_id=item.item_id AND current.current_version=(SELECT max(s.item_version) FROM definition_specs s\n   WHERE s.tenant_id=item.tenant_id AND s.item_id=item.item_id)) THEN\n  RAISE EXCEPTION 'definition item missing exact latest projection' USING ERRCODE='23514'; END IF;\n IF item.receipt_id IS NULL THEN\n  SELECT * INTO STRICT receipt FROM action_receipts r WHERE r.tenant_id=item.tenant_id AND r.category_id=item.category_id\n   AND r.product_id=item.product_id AND r.subject_type='definition_revision' AND r.subject_id=parent.id\n   AND r.subject_revision=parent.revision AND r.operation IN ('product.definition.draft','product.definition.update') AND r.xmin=ix;\n ELSE SELECT * INTO STRICT receipt FROM action_receipts WHERE tenant_id=item.tenant_id AND id=item.receipt_id; END IF;\n SELECT xmin INTO rx FROM action_receipts WHERE tenant_id=item.tenant_id AND id=receipt.id;\n IF rx IS DISTINCT FROM ix OR receipt.category_id IS DISTINCT FROM item.category_id\n  OR receipt.actor_id IS DISTINCT FROM scope_actor() OR receipt.requester_id IS DISTINCT FROM scope_requester()\n  OR receipt.run_id IS NOT NULL THEN RAISE EXCEPTION 'definition item receipt identity mismatch' USING ERRCODE='23514'; END IF;\n -- Existing native/G0 assembly remains one immutable initial snapshot.\n IF receipt.operation IN ('product.definition.draft','product.definition.update','proposal.g0.decide') THEN\n  IF item.item_id<>item.id OR item.item_version<>1 OR item.removed\n   OR ix IS DISTINCT FROM (SELECT xmin FROM definition_revisions WHERE tenant_id=item.tenant_id AND id=parent.id) THEN\n   RAISE EXCEPTION 'initial definition item is not part of creation' USING ERRCODE='23514'; END IF;\n  IF receipt.operation='proposal.g0.decide' THEN\n   IF parent.g0_decision_id IS NULL THEN RAISE EXCEPTION 'initial G0 item lacks decision' USING ERRCODE='23514'; END IF;\n   PERFORM m3_g0_derivation_assert(item.tenant_id,item.category_id,parent.g0_decision_id);\n  ELSE\n   IF receipt.product_id IS DISTINCT FROM item.product_id OR receipt.subject_type<>'definition_revision'\n    OR receipt.subject_id<>parent.id OR receipt.subject_revision<>parent.revision OR receipt.agent_run_id IS NOT NULL\n    OR receipt.actor_id<>receipt.requester_id OR parent.sealed OR parent.status<>'draft'\n    OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=item.tenant_id AND p.id=receipt.actor_id AND p.kind='human' AND p.active) THEN\n    RAISE EXCEPTION 'native definition item creation receipt mismatch' USING ERRCODE='23514'; END IF;\n   IF item.origin<>'human' OR item.run_id IS NOT NULL OR item.confirmed_by IS NOT NULL OR item.prepared_candidate_id IS NOT NULL\n    OR (item.writer_id IS NOT NULL AND item.writer_id<>receipt.actor_id) THEN\n    IF parent.parent_definition_id IS NULL OR NOT EXISTS(SELECT 1 FROM definition_specs previous\n     JOIN definition_spec_current current ON current.tenant_id=previous.tenant_id AND current.current_row_id=previous.id AND NOT current.removed\n     WHERE previous.tenant_id=item.tenant_id AND previous.category_id=item.category_id AND previous.product_id=item.product_id\n      AND previous.definition_id=parent.parent_definition_id\n      AND (to_jsonb(previous)-ARRAY['id','tenant_id','category_id','product_id','definition_id','created_at','item_id','item_version','removed','receipt_id'])\n       IS NOT DISTINCT FROM (to_jsonb(item)-ARRAY['id','tenant_id','category_id','product_id','definition_id','created_at','item_id','item_version','removed','receipt_id'])) THEN\n     RAISE EXCEPTION 'native continuation lost original provenance' USING ERRCODE='23514'; END IF;\n   END IF;\n   IF m3_definition_item_sources_valid(item.tenant_id,item.category_id,item.product_id,item.source_refs,parent.visibility='category') IS DISTINCT FROM true THEN\n    RAISE EXCEPTION 'native continuation item sources unavailable' USING ERRCODE='23514'; END IF;\n  END IF;\n  RETURN NULL;\n END IF;\n IF parent.sealed OR parent.status<>'draft' OR receipt.product_id IS DISTINCT FROM item.product_id\n  OR m3_definition_fixed_consumed(item.tenant_id,item.category_id,parent.id,parent.revision) THEN\n  RAISE EXCEPTION 'fixed definition requires continuation' USING ERRCODE='23514'; END IF;\n SELECT * INTO prior FROM definition_specs WHERE tenant_id=item.tenant_id AND item_id=item.item_id AND item_version=item.item_version-1;\n business=to_jsonb(item)-excluded;\n SELECT coalesce(jsonb_agg(jsonb_build_object('item_id',s.item_id,'item_version',s.item_version,'row_id',s.id,'key',s.key,'removed',s.removed)\n  ORDER BY s.id),'[]') INTO manifest FROM definition_specs s WHERE s.tenant_id=item.tenant_id AND s.receipt_id=receipt.id;\n IF jsonb_typeof(receipt.result->(CASE WHEN receipt.operation='ai.run.revert' THEN 'definition_item_changes' ELSE 'changes' END)) IS DISTINCT FROM 'array'\n  OR (SELECT coalesce(jsonb_agg(value ORDER BY value->>'row_id'),'[]') FROM jsonb_array_elements(receipt.result->(CASE WHEN receipt.operation='ai.run.revert' THEN 'definition_item_changes' ELSE 'changes' END))) IS DISTINCT FROM manifest THEN\n  RAISE EXCEPTION 'definition item receipt manifest mismatch' USING ERRCODE='23514'; END IF;\n IF receipt.operation='ai.run.revert' THEN\n  SELECT * INTO STRICT actual_run FROM agent_runs WHERE tenant_id=item.tenant_id AND id=receipt.subject_id;\n  PERFORM m3_evidence_revert_confirmation(item.tenant_id,item.category_id,receipt.id);\n  IF receipt.subject_type<>'agent_run' OR actual_run.revert_receipt_id IS DISTINCT FROM receipt.id\n   OR actual_run.requester_id IS DISTINCT FROM receipt.requester_id OR actual_run.product_id IS DISTINCT FROM item.product_id\n   OR actual_run.category_id IS DISTINCT FROM item.category_id OR receipt.actor_id<>receipt.requester_id\n   OR receipt.agent_run_id IS NOT NULL\n   OR prior.run_id IS DISTINCT FROM actual_run.id OR prior.origin<>'ai_draft'\n   OR prior.confirmed_by IS NOT NULL OR prior.item_status='confirmed' THEN\n   RAISE EXCEPTION 'definition item compensation identity mismatch' USING ERRCODE='23514'; END IF;\n  SELECT min(s.item_version),max(s.item_version),count(*) INTO first_version,last_version,actual_count FROM definition_specs s\n   JOIN action_receipts r ON r.tenant_id=s.tenant_id AND r.id=s.receipt_id AND r.operation='product.definition.item.patch' AND r.agent_run_id=actual_run.id\n   WHERE s.tenant_id=item.tenant_id AND s.item_id=item.item_id AND s.run_id=actual_run.id;\n  IF last_version IS DISTINCT FROM item.item_version-1 OR actual_count IS DISTINCT FROM last_version-first_version+1\n   OR EXISTS(SELECT 1 FROM definition_specs s WHERE s.tenant_id=item.tenant_id AND s.item_id=item.item_id\n    AND s.item_version BETWEEN first_version AND last_version AND (s.confirmed_by IS NOT NULL OR s.item_status='confirmed' OR s.origin<>'ai_draft' OR s.writer_id IS DISTINCT FROM actual_run.writer_id)) THEN\n   RAISE EXCEPTION 'definition item compensation lost contiguous run history' USING ERRCODE='23514'; END IF;\n  IF first_version=1 THEN expected=to_jsonb(prior)-excluded;\n   IF item.origin<>'human' OR item.writer_id IS DISTINCT FROM receipt.actor_id OR item.run_id IS NOT NULL\n    OR item.confirmed_by IS NOT NULL OR item.prepared_candidate_id IS NOT NULL THEN\n    RAISE EXCEPTION 'new item compensation must retain actual human actor' USING ERRCODE='23514'; END IF;\n   IF NOT item.removed THEN RAISE EXCEPTION 'new run item compensation requires tombstone' USING ERRCODE='23514'; END IF;\n  ELSE\n   SELECT * INTO STRICT baseline FROM definition_specs WHERE tenant_id=item.tenant_id AND item_id=item.item_id AND item_version=first_version-1;\n   expected=to_jsonb(baseline)-excluded;\n   IF ROW(item.origin,item.writer_id,item.run_id,item.confirmed_by,item.prepared_candidate_id)\n    IS DISTINCT FROM ROW(baseline.origin,baseline.writer_id,baseline.run_id,baseline.confirmed_by,baseline.prepared_candidate_id) THEN\n    RAISE EXCEPTION 'compensation must retain original value provenance' USING ERRCODE='23514'; END IF;\n   IF item.removed IS DISTINCT FROM baseline.removed THEN RAISE EXCEPTION 'compensation removed state mismatch' USING ERRCODE='23514'; END IF;\n  END IF;\n  IF business IS DISTINCT FROM expected THEN RAISE EXCEPTION 'compensation must restore exact prior values' USING ERRCODE='23514'; END IF;\n  RETURN NULL;\n END IF;\n IF receipt.operation<>'product.definition.item.patch' OR receipt.subject_type<>'definition_revision'\n  OR receipt.subject_id<>parent.id OR receipt.subject_revision<>parent.revision THEN\n  RAISE EXCEPTION 'definition patch receipt subject mismatch' USING ERRCODE='23514'; END IF;\n IF item.origin='human' THEN\n  IF item.writer_id IS DISTINCT FROM receipt.actor_id OR receipt.actor_id<>receipt.requester_id\n   OR item.run_id IS NOT NULL OR item.confirmed_by IS NOT NULL OR item.prepared_candidate_id IS NOT NULL\n   OR receipt.agent_run_id IS NOT NULL OR receipt.confirmation_id IS NOT NULL\n   OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=item.tenant_id AND p.id=item.writer_id AND p.kind='human' AND p.active) THEN\n   RAISE EXCEPTION 'definition human provenance mismatch' USING ERRCODE='23514'; END IF;\n ELSIF item.origin='ai_draft' THEN\n  SELECT * INTO STRICT actual_run FROM agent_runs WHERE tenant_id=item.tenant_id AND id=item.run_id;\n  IF actual_run.category_id IS DISTINCT FROM item.category_id OR actual_run.product_id IS DISTINCT FROM item.product_id\n   OR actual_run.requester_id IS DISTINCT FROM receipt.requester_id OR actual_run.writer_id IS DISTINCT FROM item.writer_id\n   OR actual_run.state='cancelled' OR actual_run.reverted_at IS NOT NULL\n   OR (actual_run.private_context AND parent.visibility='category')\n   OR (NOT item.removed AND item.item_status='confirmed')\n   OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=item.tenant_id AND p.id=item.writer_id AND p.kind='agent' AND p.active) THEN\n   RAISE EXCEPTION 'definition AI run provenance mismatch' USING ERRCODE='23514'; END IF;\n  IF item.confirmed_by IS NULL THEN\n   IF receipt.actor_id IS DISTINCT FROM item.writer_id OR receipt.agent_run_id IS DISTINCT FROM item.run_id\n    OR receipt.confirmation_id IS NOT NULL OR item.prepared_candidate_id IS NOT NULL\n    OR (prior.id IS NOT NULL AND (prior.origin='human' OR prior.confirmed_by IS NOT NULL OR prior.item_status='confirmed')) THEN\n    RAISE EXCEPTION 'definition T0 cannot change human values' USING ERRCODE='23514'; END IF;\n   SELECT * INTO STRICT call FROM agent_tool_calls WHERE tenant_id=item.tenant_id AND run_id=item.run_id AND receipt_id=receipt.id AND state='completed';\n   IF call.execution_binding->>'kind' IS DISTINCT FROM 'domain_t0' OR call.execution_binding->>'operation' IS DISTINCT FROM receipt.operation\n    OR (call.execution_binding->>'cancel_epoch')::integer IS DISTINCT FROM actual_run.cancel_epoch THEN\n    RAISE EXCEPTION 'definition T0 lacks actual completed command' USING ERRCODE='23514'; END IF;\n   SELECT * INTO STRICT model FROM agent_tool_calls WHERE tenant_id=item.tenant_id AND run_id=item.run_id\n    AND id=(call.execution_binding->>'model_call_id')::uuid AND state='completed';\n   IF model.execution_binding->>'kind' IS DISTINCT FROM 'model' OR model.execution_binding->>'isolation' IS DISTINCT FROM 'main'\n    OR model.execution_binding->>'model_version' IS DISTINCT FROM actual_run.versions->>'model_version'\n    OR model.execution_binding->>'model_route_digest' IS DISTINCT FROM actual_run.versions->>'model_route_digest'\n    OR model.execution_binding->>'tool_definitions_digest' IS DISTINCT FROM actual_run.versions->'tool_definitions'->>'main'\n    OR model.execution_binding->>'prompt_digest' IS DISTINCT FROM actual_run.versions->'prompt_prefixes'->>'main'\n    OR model.execution_binding->>'cancel_epoch' IS DISTINCT FROM actual_run.cancel_epoch::text\n    OR ((model.execution_binding->'loaded_skills') @> jsonb_build_array(call.execution_binding->'skill')) IS DISTINCT FROM true\n    OR model.result->'calls'->((call.execution_binding->>'response_index')::integer)->>'name' IS DISTINCT FROM receipt.operation\n    OR call.tool IS DISTINCT FROM receipt.operation\n    OR NOT EXISTS(SELECT 1 FROM agent_run_events event WHERE event.tenant_id=item.tenant_id AND event.run_id=item.run_id\n     AND event.id=(call.execution_binding->'skill'->>'load_event_id')::uuid AND event.body->>'type'='skill_loaded'\n     AND event.body->>'key'=call.execution_binding->'skill'->>'key'\n     AND event.body->>'version'=call.execution_binding->'skill'->>'version'\n     AND event.body->>'digest'=call.execution_binding->'skill'->>'digest' AND event.body->>'isolation'='main') THEN\n    RAISE EXCEPTION 'definition T0 model or actual skill mismatch' USING ERRCODE='23514'; END IF;\n   PERFORM 1 FROM tenant_skill_enablements enablement WHERE enablement.tenant_id=item.tenant_id\n    AND enablement.skill_key=call.execution_binding->'skill'->>'key' AND enablement.enabled AND enablement.pilot\n    AND NOT enablement.qualification_revoked AND enablement.qualified_skill_version=call.execution_binding->'skill'->>'version'\n    AND enablement.qualified_model_version=model.execution_binding->>'model_version'\n    AND enablement.reviewed_by IS NOT NULL AND enablement.reviewed_at IS NOT NULL\n    AND (SELECT count(DISTINCT value) FROM jsonb_array_elements(enablement.review_case_refs))>=10 FOR SHARE;\n   IF NOT FOUND THEN RAISE EXCEPTION 'definition T0 qualification unavailable' USING ERRCODE='23514'; END IF;\n   payload=model.result->'calls'->((call.execution_binding->>'response_index')::integer)->'arguments';\n  ELSE\n   SELECT * INTO STRICT candidate FROM proposal_prepared_candidates WHERE tenant_id=item.tenant_id AND id=item.prepared_candidate_id;\n   SELECT * INTO STRICT confirmation FROM confirmations WHERE tenant_id=item.tenant_id AND id=receipt.confirmation_id;\n   IF item.confirmed_by IS DISTINCT FROM receipt.actor_id OR receipt.actor_id<>receipt.requester_id\n    OR receipt.agent_run_id IS DISTINCT FROM item.run_id OR candidate.category_id<>item.category_id\n    OR candidate.run_id<>item.run_id OR candidate.writer_id<>item.writer_id OR candidate.requester_id<>receipt.requester_id\n    OR candidate.operation<>receipt.operation OR (candidate.execution_binding->'model'->>'cancel_epoch')::integer IS DISTINCT FROM actual_run.cancel_epoch\n    OR confirmation.consumed IS DISTINCT FROM true OR confirmation.actor_id<>receipt.actor_id\n    OR confirmation.category_id<>item.category_id OR confirmation.product_id IS DISTINCT FROM item.product_id\n    OR confirmation.operation<>receipt.operation OR confirmation.subject_type<>'definition_revision'\n    OR confirmation.subject_id<>parent.id OR confirmation.revision<>parent.revision\n    OR (SELECT xmin FROM confirmations WHERE tenant_id=item.tenant_id AND id=confirmation.id) IS DISTINCT FROM rx\n    OR confirmation.snapshot->'payload'->>'prepared_by_run_id' IS DISTINCT FROM item.run_id::text\n    OR confirmation.snapshot->'payload'->>'candidate_digest' IS DISTINCT FROM candidate.candidate_digest\n    OR ((confirmation.snapshot->'payload')-ARRAY['prepared_by_run_id','candidate_digest','confirmation_token']) IS DISTINCT FROM candidate.payload THEN\n    RAISE EXCEPTION 'definition T1 candidate or consumed confirmation mismatch' USING ERRCODE='23514'; END IF;\n   SELECT * INTO STRICT model FROM agent_tool_calls WHERE tenant_id=item.tenant_id AND run_id=item.run_id\n    AND id=(candidate.execution_binding->>'model_call_id')::uuid AND state='completed';\n   IF model.execution_binding IS DISTINCT FROM candidate.execution_binding->'model'\n    OR model.execution_binding->>'kind' IS DISTINCT FROM 'model'\n    OR model.execution_binding->>'isolation' IS DISTINCT FROM 'main'\n    OR ((model.execution_binding->'loaded_skills') @> jsonb_build_array(candidate.execution_binding->'skill')) IS DISTINCT FROM true\n    OR model.execution_binding->>'cancel_epoch' IS DISTINCT FROM actual_run.cancel_epoch::text\n    OR NOT EXISTS(SELECT 1 FROM agent_run_events event WHERE event.tenant_id=item.tenant_id AND event.run_id=item.run_id\n     AND event.id=(candidate.execution_binding->'skill'->>'load_event_id')::uuid AND event.body->>'type'='skill_loaded'\n     AND event.body->>'key'=candidate.execution_binding->'skill'->>'key'\n     AND event.body->>'version'=candidate.execution_binding->'skill'->>'version'\n     AND event.body->>'digest'=candidate.execution_binding->'skill'->>'digest' AND event.body->>'isolation'='main')\n    OR model.result->'calls'->((candidate.execution_binding->>'response_index')::integer)->>'name' IS DISTINCT FROM receipt.operation THEN\n    RAISE EXCEPTION 'definition candidate lacks actual model and loaded skill' USING ERRCODE='23514'; END IF;\n   payload=candidate.payload;\n  END IF;\n  IF payload->>'definition_id' IS DISTINCT FROM parent.id::text OR jsonb_typeof(payload->'ops') IS DISTINCT FROM 'array' THEN\n   RAISE EXCEPTION 'definition candidate payload scope mismatch' USING ERRCODE='23514'; END IF;\n  IF jsonb_array_length(payload->'ops')<>(SELECT count(*) FROM definition_specs spec_row WHERE spec_row.tenant_id=item.tenant_id AND spec_row.receipt_id=receipt.id)\n   OR (item.confirmed_by IS NOT NULL AND jsonb_array_length(model.result->'calls'->((candidate.execution_binding->>'response_index')::integer)->'arguments'->'ops')<>jsonb_array_length(payload->'ops')) THEN\n   RAISE EXCEPTION 'definition candidate operation set differs from committed manifest' USING ERRCODE='23514'; END IF;\n  SELECT op INTO STRICT operation FROM jsonb_array_elements(payload->'ops') op\n   WHERE (item.item_version>1 AND op->>'item_id'=item.item_id::text AND op->'base_version'=to_jsonb(item.item_version-1))\n    OR (item.item_version=1 AND op->>'item_id' IS NULL AND op->'content'->>'key'=item.key);\n  IF item.confirmed_by IS NOT NULL THEN\n   SELECT op INTO STRICT expected FROM jsonb_array_elements(model.result->'calls'->((candidate.execution_binding->>'response_index')::integer)->'arguments'->'ops') op\n    WHERE (item.item_version>1 AND op->>'item_id'=item.item_id::text AND op->'base_version'=to_jsonb(item.item_version-1))\n     OR (item.item_version=1 AND op->>'item_id' IS NULL AND op->'content'->>'key'=item.key);\n   IF model.result->'calls'->((candidate.execution_binding->>'response_index')::integer)->'arguments'->>'definition_id' IS DISTINCT FROM parent.id::text\n    OR coalesce(expected->>'op','upsert') IS DISTINCT FROM coalesce(operation->>'op','upsert')\n    OR (NOT item.removed AND m3_definition_item_content(expected->'content',expected->'source_refs')\n     IS DISTINCT FROM m3_definition_item_content(operation->'content',operation->'source_refs')) THEN\n    RAISE EXCEPTION 'definition prepared candidate changed actual model values' USING ERRCODE='23514'; END IF;\n  END IF;\n  IF item.removed IS DISTINCT FROM (coalesce(operation->>'op','upsert')='remove') THEN\n   RAISE EXCEPTION 'definition candidate action mismatch' USING ERRCODE='23514'; END IF;\n  IF NOT item.removed AND business IS DISTINCT FROM m3_definition_item_content(operation->'content',operation->'source_refs') THEN\n   RAISE EXCEPTION 'definition candidate content differs from actual model values' USING ERRCODE='23514'; END IF;\n ELSE RAISE EXCEPTION 'definition patch has unsupported origin' USING ERRCODE='23514'; END IF;\n IF item.removed THEN\n  IF prior.id IS NULL OR prior.removed OR business IS DISTINCT FROM (to_jsonb(prior)-excluded) THEN\n   RAISE EXCEPTION 'definition removal must retain complete previous values' USING ERRCODE='23514'; END IF;\n  RETURN NULL;\n END IF;\n IF (item.parameter_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM parameter_versions pv WHERE pv.tenant_id=item.tenant_id\n  AND pv.category_id=item.category_id AND pv.parameter_id=item.parameter_id AND pv.version=item.parameter_version\n  AND pv.key=item.key AND pv.value_type=item.value_type AND pv.unit IS NOT DISTINCT FROM item.unit))\n  OR (item.owner_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM principals p JOIN grants g ON g.tenant_id=p.tenant_id AND g.principal_id=p.id\n   WHERE p.tenant_id=item.tenant_id AND p.id=item.owner_id AND p.kind='human' AND p.active AND g.category_id=item.category_id\n    AND (g.expires_at IS NULL OR g.expires_at>statement_timestamp())))\n  OR (item.item_status='confirmed' AND (item.availability NOT IN ('known','not_applicable') OR jsonb_array_length(item.source_refs)=0))\n  OR (item.availability='not_applicable' AND nullif(item.reason,'') IS NULL)\n  OR (item.value_type='boolean' AND item.availability='known' AND item.text NOT IN ('true','false'))\n  OR item.value::text IN ('NaN','Infinity','-Infinity') OR item.lower::text IN ('NaN','Infinity','-Infinity')\n  OR item.upper::text IN ('NaN','Infinity','-Infinity') OR item.tolerance::text IN ('NaN','Infinity','-Infinity')\n  OR m3_definition_item_sources_valid(item.tenant_id,item.category_id,item.product_id,item.source_refs,parent.visibility='category') IS DISTINCT FROM true THEN\n  RAISE EXCEPTION 'definition item dictionary, member or source proof mismatch' USING ERRCODE='23514'; END IF;\n RETURN NULL;\nEND $function$\n",
)

DOWNGRADE_SQL = (
    "CREATE OR REPLACE FUNCTION public.protect_fixed_definition()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\n BEGIN\n IF TG_OP='UPDATE' THEN\n IF TG_TABLE_NAME='definition_specs' THEN\n IF OLD.receipt_id IS NULL AND NEW.receipt_id IS NOT NULL\n  AND (to_jsonb(NEW)-'receipt_id') IS NOT DISTINCT FROM (to_jsonb(OLD)-'receipt_id')\n  AND EXISTS(SELECT 1 FROM action_receipts receipt JOIN definition_specs spec\n   ON spec.tenant_id=receipt.tenant_id AND spec.id=NEW.id AND spec.xmin=receipt.xmin\n   WHERE receipt.tenant_id=NEW.tenant_id AND receipt.id=NEW.receipt_id\n    AND receipt.operation IN ('product.definition.item.patch','product.definition.draft')\n    AND receipt.subject_id=NEW.definition_id AND receipt.subject_type='definition_revision'\n    AND receipt.category_id=NEW.category_id AND receipt.product_id=NEW.product_id\n    AND receipt.actor_id=scope_actor() AND receipt.requester_id=scope_requester()) THEN RETURN NEW; END IF;\n ELSIF TG_TABLE_NAME='definition_revisions' THEN\n IF current_user='pdos_next_owner'\n  AND OLD.status='draft' AND NOT OLD.sealed AND NEW.status='published' AND NEW.sealed\n  AND (to_jsonb(NEW)-ARRAY['status','sealed','publication_receipt_id']) IS NOT DISTINCT FROM\n      (to_jsonb(OLD)-ARRAY['status','sealed','publication_receipt_id']) THEN RETURN NEW; END IF;\n IF (to_jsonb(OLD)->>'sealed')='false' AND (to_jsonb(NEW)->>'sealed')='true'\n AND (to_jsonb(NEW)-ARRAY['sealed','source_proposal_id','source_submission_id','source_proposal_revision','g0_decision_id'])\n   =(to_jsonb(OLD)-ARRAY['sealed','source_proposal_id','source_submission_id','source_proposal_revision','g0_decision_id'])\n AND m3_result_access(NEW.tenant_id,NEW.category_id,'definition_revisions',NEW.id)\n THEN RETURN NEW; END IF;\n END IF;\n END IF;\n RAISE EXCEPTION 'definition snapshots are immutable'; END $function$\n",
    "CREATE OR REPLACE FUNCTION public.m3_definition_item_atom()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE item definition_specs; prior definition_specs; baseline definition_specs; parent definition_revisions;\n receipt action_receipts; actual_run agent_runs; candidate proposal_prepared_candidates; confirmation confirmations;\n call agent_tool_calls; model agent_tool_calls; rx xid; ix xid; payload jsonb; operation jsonb; manifest jsonb;\n business jsonb; expected jsonb; first_version integer; last_version integer; actual_count integer;\n excluded text[]=ARRAY['id','tenant_id','category_id','product_id','definition_id','created_at',\n  'item_id','item_version','removed','prepared_candidate_id','origin','writer_id','run_id','confirmed_by','receipt_id'];\nBEGIN\n SELECT * INTO STRICT item FROM definition_specs WHERE tenant_id=NEW.tenant_id AND id=NEW.id;\n SELECT * INTO STRICT parent FROM definition_revisions WHERE tenant_id=item.tenant_id AND category_id=item.category_id\n  AND product_id=item.product_id AND id=item.definition_id FOR UPDATE;\n SELECT xmin INTO ix FROM definition_specs WHERE tenant_id=item.tenant_id AND id=item.id;\n IF NOT EXISTS(SELECT 1 FROM definition_spec_current current WHERE current.tenant_id=item.tenant_id\n  AND current.category_id=item.category_id AND current.product_id=item.product_id AND current.definition_id=item.definition_id\n  AND current.item_id=item.item_id AND current.current_version=(SELECT max(s.item_version) FROM definition_specs s\n   WHERE s.tenant_id=item.tenant_id AND s.item_id=item.item_id)) THEN\n  RAISE EXCEPTION 'definition item missing exact latest projection' USING ERRCODE='23514'; END IF;\n IF item.receipt_id IS NULL THEN\n  SELECT * INTO STRICT receipt FROM action_receipts r WHERE r.tenant_id=item.tenant_id AND r.category_id=item.category_id\n   AND r.product_id=item.product_id AND r.subject_type='definition_revision' AND r.subject_id=parent.id\n   AND r.subject_revision=parent.revision AND r.operation='product.definition.draft' AND r.xmin=ix;\n ELSE SELECT * INTO STRICT receipt FROM action_receipts WHERE tenant_id=item.tenant_id AND id=item.receipt_id; END IF;\n SELECT xmin INTO rx FROM action_receipts WHERE tenant_id=item.tenant_id AND id=receipt.id;\n IF rx IS DISTINCT FROM ix OR receipt.category_id IS DISTINCT FROM item.category_id\n  OR receipt.actor_id IS DISTINCT FROM scope_actor() OR receipt.requester_id IS DISTINCT FROM scope_requester()\n  OR receipt.run_id IS NOT NULL THEN RAISE EXCEPTION 'definition item receipt identity mismatch' USING ERRCODE='23514'; END IF;\n -- Existing native/G0 assembly remains one immutable initial snapshot.\n IF receipt.operation IN ('product.definition.draft','proposal.g0.decide') THEN\n  IF item.item_id<>item.id OR item.item_version<>1 OR item.removed\n   OR ix IS DISTINCT FROM (SELECT xmin FROM definition_revisions WHERE tenant_id=item.tenant_id AND id=parent.id) THEN\n   RAISE EXCEPTION 'initial definition item is not part of creation' USING ERRCODE='23514'; END IF;\n  IF receipt.operation='proposal.g0.decide' THEN\n   IF parent.g0_decision_id IS NULL THEN RAISE EXCEPTION 'initial G0 item lacks decision' USING ERRCODE='23514'; END IF;\n   PERFORM m3_g0_derivation_assert(item.tenant_id,item.category_id,parent.g0_decision_id);\n  ELSE\n   IF receipt.product_id IS DISTINCT FROM item.product_id OR receipt.subject_type<>'definition_revision'\n    OR receipt.subject_id<>parent.id OR receipt.subject_revision<>parent.revision OR receipt.agent_run_id IS NOT NULL\n    OR receipt.actor_id<>receipt.requester_id OR parent.sealed OR parent.status<>'draft'\n    OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=item.tenant_id AND p.id=receipt.actor_id AND p.kind='human' AND p.active) THEN\n    RAISE EXCEPTION 'native definition item creation receipt mismatch' USING ERRCODE='23514'; END IF;\n   IF item.origin<>'human' OR item.run_id IS NOT NULL OR item.confirmed_by IS NOT NULL OR item.prepared_candidate_id IS NOT NULL\n    OR (item.writer_id IS NOT NULL AND item.writer_id<>receipt.actor_id) THEN\n    IF parent.parent_definition_id IS NULL OR NOT EXISTS(SELECT 1 FROM definition_specs previous\n     JOIN definition_spec_current current ON current.tenant_id=previous.tenant_id AND current.current_row_id=previous.id AND NOT current.removed\n     WHERE previous.tenant_id=item.tenant_id AND previous.category_id=item.category_id AND previous.product_id=item.product_id\n      AND previous.definition_id=parent.parent_definition_id\n      AND (to_jsonb(previous)-ARRAY['id','tenant_id','category_id','product_id','definition_id','created_at','item_id','item_version','removed','receipt_id'])\n       IS NOT DISTINCT FROM (to_jsonb(item)-ARRAY['id','tenant_id','category_id','product_id','definition_id','created_at','item_id','item_version','removed','receipt_id'])) THEN\n     RAISE EXCEPTION 'native continuation lost original provenance' USING ERRCODE='23514'; END IF;\n   END IF;\n   IF m3_definition_item_sources_valid(item.tenant_id,item.category_id,item.product_id,item.source_refs,parent.visibility='category') IS DISTINCT FROM true THEN\n    RAISE EXCEPTION 'native continuation item sources unavailable' USING ERRCODE='23514'; END IF;\n  END IF;\n  RETURN NULL;\n END IF;\n IF parent.sealed OR parent.status<>'draft' OR receipt.product_id IS DISTINCT FROM item.product_id\n  OR m3_definition_fixed_consumed(item.tenant_id,item.category_id,parent.id,parent.revision) THEN\n  RAISE EXCEPTION 'fixed definition requires continuation' USING ERRCODE='23514'; END IF;\n SELECT * INTO prior FROM definition_specs WHERE tenant_id=item.tenant_id AND item_id=item.item_id AND item_version=item.item_version-1;\n business=to_jsonb(item)-excluded;\n SELECT coalesce(jsonb_agg(jsonb_build_object('item_id',s.item_id,'item_version',s.item_version,'row_id',s.id,'key',s.key,'removed',s.removed)\n  ORDER BY s.id),'[]') INTO manifest FROM definition_specs s WHERE s.tenant_id=item.tenant_id AND s.receipt_id=receipt.id;\n IF jsonb_typeof(receipt.result->(CASE WHEN receipt.operation='ai.run.revert' THEN 'definition_item_changes' ELSE 'changes' END)) IS DISTINCT FROM 'array'\n  OR (SELECT coalesce(jsonb_agg(value ORDER BY value->>'row_id'),'[]') FROM jsonb_array_elements(receipt.result->(CASE WHEN receipt.operation='ai.run.revert' THEN 'definition_item_changes' ELSE 'changes' END))) IS DISTINCT FROM manifest THEN\n  RAISE EXCEPTION 'definition item receipt manifest mismatch' USING ERRCODE='23514'; END IF;\n IF receipt.operation='ai.run.revert' THEN\n  SELECT * INTO STRICT actual_run FROM agent_runs WHERE tenant_id=item.tenant_id AND id=receipt.subject_id;\n  PERFORM m3_evidence_revert_confirmation(item.tenant_id,item.category_id,receipt.id);\n  IF receipt.subject_type<>'agent_run' OR actual_run.revert_receipt_id IS DISTINCT FROM receipt.id\n   OR actual_run.requester_id IS DISTINCT FROM receipt.requester_id OR actual_run.product_id IS DISTINCT FROM item.product_id\n   OR actual_run.category_id IS DISTINCT FROM item.category_id OR receipt.actor_id<>receipt.requester_id\n   OR receipt.agent_run_id IS NOT NULL\n   OR prior.run_id IS DISTINCT FROM actual_run.id OR prior.origin<>'ai_draft'\n   OR prior.confirmed_by IS NOT NULL OR prior.item_status='confirmed' THEN\n   RAISE EXCEPTION 'definition item compensation identity mismatch' USING ERRCODE='23514'; END IF;\n  SELECT min(s.item_version),max(s.item_version),count(*) INTO first_version,last_version,actual_count FROM definition_specs s\n   JOIN action_receipts r ON r.tenant_id=s.tenant_id AND r.id=s.receipt_id AND r.operation='product.definition.item.patch' AND r.agent_run_id=actual_run.id\n   WHERE s.tenant_id=item.tenant_id AND s.item_id=item.item_id AND s.run_id=actual_run.id;\n  IF last_version IS DISTINCT FROM item.item_version-1 OR actual_count IS DISTINCT FROM last_version-first_version+1\n   OR EXISTS(SELECT 1 FROM definition_specs s WHERE s.tenant_id=item.tenant_id AND s.item_id=item.item_id\n    AND s.item_version BETWEEN first_version AND last_version AND (s.confirmed_by IS NOT NULL OR s.item_status='confirmed' OR s.origin<>'ai_draft' OR s.writer_id IS DISTINCT FROM actual_run.writer_id)) THEN\n   RAISE EXCEPTION 'definition item compensation lost contiguous run history' USING ERRCODE='23514'; END IF;\n  IF first_version=1 THEN expected=to_jsonb(prior)-excluded;\n   IF item.origin<>'human' OR item.writer_id IS DISTINCT FROM receipt.actor_id OR item.run_id IS NOT NULL\n    OR item.confirmed_by IS NOT NULL OR item.prepared_candidate_id IS NOT NULL THEN\n    RAISE EXCEPTION 'new item compensation must retain actual human actor' USING ERRCODE='23514'; END IF;\n   IF NOT item.removed THEN RAISE EXCEPTION 'new run item compensation requires tombstone' USING ERRCODE='23514'; END IF;\n  ELSE\n   SELECT * INTO STRICT baseline FROM definition_specs WHERE tenant_id=item.tenant_id AND item_id=item.item_id AND item_version=first_version-1;\n   expected=to_jsonb(baseline)-excluded;\n   IF ROW(item.origin,item.writer_id,item.run_id,item.confirmed_by,item.prepared_candidate_id)\n    IS DISTINCT FROM ROW(baseline.origin,baseline.writer_id,baseline.run_id,baseline.confirmed_by,baseline.prepared_candidate_id) THEN\n    RAISE EXCEPTION 'compensation must retain original value provenance' USING ERRCODE='23514'; END IF;\n   IF item.removed IS DISTINCT FROM baseline.removed THEN RAISE EXCEPTION 'compensation removed state mismatch' USING ERRCODE='23514'; END IF;\n  END IF;\n  IF business IS DISTINCT FROM expected THEN RAISE EXCEPTION 'compensation must restore exact prior values' USING ERRCODE='23514'; END IF;\n  RETURN NULL;\n END IF;\n IF receipt.operation<>'product.definition.item.patch' OR receipt.subject_type<>'definition_revision'\n  OR receipt.subject_id<>parent.id OR receipt.subject_revision<>parent.revision THEN\n  RAISE EXCEPTION 'definition patch receipt subject mismatch' USING ERRCODE='23514'; END IF;\n IF item.origin='human' THEN\n  IF item.writer_id IS DISTINCT FROM receipt.actor_id OR receipt.actor_id<>receipt.requester_id\n   OR item.run_id IS NOT NULL OR item.confirmed_by IS NOT NULL OR item.prepared_candidate_id IS NOT NULL\n   OR receipt.agent_run_id IS NOT NULL OR receipt.confirmation_id IS NOT NULL\n   OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=item.tenant_id AND p.id=item.writer_id AND p.kind='human' AND p.active) THEN\n   RAISE EXCEPTION 'definition human provenance mismatch' USING ERRCODE='23514'; END IF;\n ELSIF item.origin='ai_draft' THEN\n  SELECT * INTO STRICT actual_run FROM agent_runs WHERE tenant_id=item.tenant_id AND id=item.run_id;\n  IF actual_run.category_id IS DISTINCT FROM item.category_id OR actual_run.product_id IS DISTINCT FROM item.product_id\n   OR actual_run.requester_id IS DISTINCT FROM receipt.requester_id OR actual_run.writer_id IS DISTINCT FROM item.writer_id\n   OR actual_run.state='cancelled' OR actual_run.reverted_at IS NOT NULL\n   OR (actual_run.private_context AND parent.visibility='category')\n   OR (NOT item.removed AND item.item_status='confirmed')\n   OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=item.tenant_id AND p.id=item.writer_id AND p.kind='agent' AND p.active) THEN\n   RAISE EXCEPTION 'definition AI run provenance mismatch' USING ERRCODE='23514'; END IF;\n  IF item.confirmed_by IS NULL THEN\n   IF receipt.actor_id IS DISTINCT FROM item.writer_id OR receipt.agent_run_id IS DISTINCT FROM item.run_id\n    OR receipt.confirmation_id IS NOT NULL OR item.prepared_candidate_id IS NOT NULL\n    OR (prior.id IS NOT NULL AND (prior.origin='human' OR prior.confirmed_by IS NOT NULL OR prior.item_status='confirmed')) THEN\n    RAISE EXCEPTION 'definition T0 cannot change human values' USING ERRCODE='23514'; END IF;\n   SELECT * INTO STRICT call FROM agent_tool_calls WHERE tenant_id=item.tenant_id AND run_id=item.run_id AND receipt_id=receipt.id AND state='completed';\n   IF call.execution_binding->>'kind' IS DISTINCT FROM 'domain_t0' OR call.execution_binding->>'operation' IS DISTINCT FROM receipt.operation\n    OR (call.execution_binding->>'cancel_epoch')::integer IS DISTINCT FROM actual_run.cancel_epoch THEN\n    RAISE EXCEPTION 'definition T0 lacks actual completed command' USING ERRCODE='23514'; END IF;\n   SELECT * INTO STRICT model FROM agent_tool_calls WHERE tenant_id=item.tenant_id AND run_id=item.run_id\n    AND id=(call.execution_binding->>'model_call_id')::uuid AND state='completed';\n   IF model.execution_binding->>'kind' IS DISTINCT FROM 'model' OR model.execution_binding->>'isolation' IS DISTINCT FROM 'main'\n    OR model.execution_binding->>'model_version' IS DISTINCT FROM actual_run.versions->>'model_version'\n    OR model.execution_binding->>'model_route_digest' IS DISTINCT FROM actual_run.versions->>'model_route_digest'\n    OR model.execution_binding->>'tool_definitions_digest' IS DISTINCT FROM actual_run.versions->'tool_definitions'->>'main'\n    OR model.execution_binding->>'prompt_digest' IS DISTINCT FROM actual_run.versions->'prompt_prefixes'->>'main'\n    OR model.execution_binding->>'cancel_epoch' IS DISTINCT FROM actual_run.cancel_epoch::text\n    OR ((model.execution_binding->'loaded_skills') @> jsonb_build_array(call.execution_binding->'skill')) IS DISTINCT FROM true\n    OR model.result->'calls'->((call.execution_binding->>'response_index')::integer)->>'name' IS DISTINCT FROM receipt.operation\n    OR call.tool IS DISTINCT FROM receipt.operation\n    OR NOT EXISTS(SELECT 1 FROM agent_run_events event WHERE event.tenant_id=item.tenant_id AND event.run_id=item.run_id\n     AND event.id=(call.execution_binding->'skill'->>'load_event_id')::uuid AND event.body->>'type'='skill_loaded'\n     AND event.body->>'key'=call.execution_binding->'skill'->>'key'\n     AND event.body->>'version'=call.execution_binding->'skill'->>'version'\n     AND event.body->>'digest'=call.execution_binding->'skill'->>'digest' AND event.body->>'isolation'='main') THEN\n    RAISE EXCEPTION 'definition T0 model or actual skill mismatch' USING ERRCODE='23514'; END IF;\n   PERFORM 1 FROM tenant_skill_enablements enablement WHERE enablement.tenant_id=item.tenant_id\n    AND enablement.skill_key=call.execution_binding->'skill'->>'key' AND enablement.enabled AND enablement.pilot\n    AND NOT enablement.qualification_revoked AND enablement.qualified_skill_version=call.execution_binding->'skill'->>'version'\n    AND enablement.qualified_model_version=model.execution_binding->>'model_version'\n    AND enablement.reviewed_by IS NOT NULL AND enablement.reviewed_at IS NOT NULL\n    AND (SELECT count(DISTINCT value) FROM jsonb_array_elements(enablement.review_case_refs))>=10 FOR SHARE;\n   IF NOT FOUND THEN RAISE EXCEPTION 'definition T0 qualification unavailable' USING ERRCODE='23514'; END IF;\n   payload=model.result->'calls'->((call.execution_binding->>'response_index')::integer)->'arguments';\n  ELSE\n   SELECT * INTO STRICT candidate FROM proposal_prepared_candidates WHERE tenant_id=item.tenant_id AND id=item.prepared_candidate_id;\n   SELECT * INTO STRICT confirmation FROM confirmations WHERE tenant_id=item.tenant_id AND id=receipt.confirmation_id;\n   IF item.confirmed_by IS DISTINCT FROM receipt.actor_id OR receipt.actor_id<>receipt.requester_id\n    OR receipt.agent_run_id IS DISTINCT FROM item.run_id OR candidate.category_id<>item.category_id\n    OR candidate.run_id<>item.run_id OR candidate.writer_id<>item.writer_id OR candidate.requester_id<>receipt.requester_id\n    OR candidate.operation<>receipt.operation OR (candidate.execution_binding->'model'->>'cancel_epoch')::integer IS DISTINCT FROM actual_run.cancel_epoch\n    OR confirmation.consumed IS DISTINCT FROM true OR confirmation.actor_id<>receipt.actor_id\n    OR confirmation.category_id<>item.category_id OR confirmation.product_id IS DISTINCT FROM item.product_id\n    OR confirmation.operation<>receipt.operation OR confirmation.subject_type<>'definition_revision'\n    OR confirmation.subject_id<>parent.id OR confirmation.revision<>parent.revision\n    OR (SELECT xmin FROM confirmations WHERE tenant_id=item.tenant_id AND id=confirmation.id) IS DISTINCT FROM rx\n    OR confirmation.snapshot->'payload'->>'prepared_by_run_id' IS DISTINCT FROM item.run_id::text\n    OR confirmation.snapshot->'payload'->>'candidate_digest' IS DISTINCT FROM candidate.candidate_digest\n    OR ((confirmation.snapshot->'payload')-ARRAY['prepared_by_run_id','candidate_digest','confirmation_token']) IS DISTINCT FROM candidate.payload THEN\n    RAISE EXCEPTION 'definition T1 candidate or consumed confirmation mismatch' USING ERRCODE='23514'; END IF;\n   SELECT * INTO STRICT model FROM agent_tool_calls WHERE tenant_id=item.tenant_id AND run_id=item.run_id\n    AND id=(candidate.execution_binding->>'model_call_id')::uuid AND state='completed';\n   IF model.execution_binding IS DISTINCT FROM candidate.execution_binding->'model'\n    OR model.execution_binding->>'kind' IS DISTINCT FROM 'model'\n    OR model.execution_binding->>'isolation' IS DISTINCT FROM 'main'\n    OR ((model.execution_binding->'loaded_skills') @> jsonb_build_array(candidate.execution_binding->'skill')) IS DISTINCT FROM true\n    OR model.execution_binding->>'cancel_epoch' IS DISTINCT FROM actual_run.cancel_epoch::text\n    OR NOT EXISTS(SELECT 1 FROM agent_run_events event WHERE event.tenant_id=item.tenant_id AND event.run_id=item.run_id\n     AND event.id=(candidate.execution_binding->'skill'->>'load_event_id')::uuid AND event.body->>'type'='skill_loaded'\n     AND event.body->>'key'=candidate.execution_binding->'skill'->>'key'\n     AND event.body->>'version'=candidate.execution_binding->'skill'->>'version'\n     AND event.body->>'digest'=candidate.execution_binding->'skill'->>'digest' AND event.body->>'isolation'='main')\n    OR model.result->'calls'->((candidate.execution_binding->>'response_index')::integer)->>'name' IS DISTINCT FROM receipt.operation THEN\n    RAISE EXCEPTION 'definition candidate lacks actual model and loaded skill' USING ERRCODE='23514'; END IF;\n   payload=candidate.payload;\n  END IF;\n  IF payload->>'definition_id' IS DISTINCT FROM parent.id::text OR jsonb_typeof(payload->'ops') IS DISTINCT FROM 'array' THEN\n   RAISE EXCEPTION 'definition candidate payload scope mismatch' USING ERRCODE='23514'; END IF;\n  IF jsonb_array_length(payload->'ops')<>(SELECT count(*) FROM definition_specs spec_row WHERE spec_row.tenant_id=item.tenant_id AND spec_row.receipt_id=receipt.id)\n   OR (item.confirmed_by IS NOT NULL AND jsonb_array_length(model.result->'calls'->((candidate.execution_binding->>'response_index')::integer)->'arguments'->'ops')<>jsonb_array_length(payload->'ops')) THEN\n   RAISE EXCEPTION 'definition candidate operation set differs from committed manifest' USING ERRCODE='23514'; END IF;\n  SELECT op INTO STRICT operation FROM jsonb_array_elements(payload->'ops') op\n   WHERE (item.item_version>1 AND op->>'item_id'=item.item_id::text AND op->'base_version'=to_jsonb(item.item_version-1))\n    OR (item.item_version=1 AND op->>'item_id' IS NULL AND op->'content'->>'key'=item.key);\n  IF item.confirmed_by IS NOT NULL THEN\n   SELECT op INTO STRICT expected FROM jsonb_array_elements(model.result->'calls'->((candidate.execution_binding->>'response_index')::integer)->'arguments'->'ops') op\n    WHERE (item.item_version>1 AND op->>'item_id'=item.item_id::text AND op->'base_version'=to_jsonb(item.item_version-1))\n     OR (item.item_version=1 AND op->>'item_id' IS NULL AND op->'content'->>'key'=item.key);\n   IF model.result->'calls'->((candidate.execution_binding->>'response_index')::integer)->'arguments'->>'definition_id' IS DISTINCT FROM parent.id::text\n    OR coalesce(expected->>'op','upsert') IS DISTINCT FROM coalesce(operation->>'op','upsert')\n    OR (NOT item.removed AND m3_definition_item_content(expected->'content',expected->'source_refs')\n     IS DISTINCT FROM m3_definition_item_content(operation->'content',operation->'source_refs')) THEN\n    RAISE EXCEPTION 'definition prepared candidate changed actual model values' USING ERRCODE='23514'; END IF;\n  END IF;\n  IF item.removed IS DISTINCT FROM (coalesce(operation->>'op','upsert')='remove') THEN\n   RAISE EXCEPTION 'definition candidate action mismatch' USING ERRCODE='23514'; END IF;\n  IF NOT item.removed AND business IS DISTINCT FROM m3_definition_item_content(operation->'content',operation->'source_refs') THEN\n   RAISE EXCEPTION 'definition candidate content differs from actual model values' USING ERRCODE='23514'; END IF;\n ELSE RAISE EXCEPTION 'definition patch has unsupported origin' USING ERRCODE='23514'; END IF;\n IF item.removed THEN\n  IF prior.id IS NULL OR prior.removed OR business IS DISTINCT FROM (to_jsonb(prior)-excluded) THEN\n   RAISE EXCEPTION 'definition removal must retain complete previous values' USING ERRCODE='23514'; END IF;\n  RETURN NULL;\n END IF;\n IF (item.parameter_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM parameter_versions pv WHERE pv.tenant_id=item.tenant_id\n  AND pv.category_id=item.category_id AND pv.parameter_id=item.parameter_id AND pv.version=item.parameter_version\n  AND pv.key=item.key AND pv.value_type=item.value_type AND pv.unit IS NOT DISTINCT FROM item.unit))\n  OR (item.owner_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM principals p JOIN grants g ON g.tenant_id=p.tenant_id AND g.principal_id=p.id\n   WHERE p.tenant_id=item.tenant_id AND p.id=item.owner_id AND p.kind='human' AND p.active AND g.category_id=item.category_id\n    AND (g.expires_at IS NULL OR g.expires_at>statement_timestamp())))\n  OR (item.item_status='confirmed' AND (item.availability NOT IN ('known','not_applicable') OR jsonb_array_length(item.source_refs)=0))\n  OR (item.availability='not_applicable' AND nullif(item.reason,'') IS NULL)\n  OR (item.value_type='boolean' AND item.availability='known' AND item.text NOT IN ('true','false'))\n  OR item.value::text IN ('NaN','Infinity','-Infinity') OR item.lower::text IN ('NaN','Infinity','-Infinity')\n  OR item.upper::text IN ('NaN','Infinity','-Infinity') OR item.tolerance::text IN ('NaN','Infinity','-Infinity')\n  OR m3_definition_item_sources_valid(item.tenant_id,item.category_id,item.product_id,item.source_refs,parent.visibility='category') IS DISTINCT FROM true THEN\n  RAISE EXCEPTION 'definition item dictionary, member or source proof mismatch' USING ERRCODE='23514'; END IF;\n RETURN NULL;\nEND $function$\n",
)
